async function crash(mode:string,db:typeof orders,extra:Record<string,string>={}){
 const child=fork(new URL('./refund-crash.ts',import.meta.url),[],{execArgv:['--import','tsx'],env:{...process.env,TEST_POOL:JSON.stringify({...db.config,options:`-c search_path=${db.schema}`}),TEST_MODE:mode,TEST_KEYS:JSON.stringify(keys),TEST_USER:userId,TEST_SNAPSHOT:JSON.stringify(snapshot),TEST_PROVIDER:providerUrl,...extra},stdio:['ignore','ignore','pipe','ipc']});children.push(child);let diagnostic='';child.stderr?.on('data',chunk=>{diagnostic+=chunk.toString();});
 await new Promise<void>((resolve,reject)=>{const timer=setTimeout(()=>{child.kill('SIGKILL');reject(new Error('Crash fixture timed out'));},10000);child.once('error',reject);child.once('exit',()=>{clearTimeout(timer);resolve();});});expect(child.signalCode,diagnostic).toBe('SIGKILL');
}
