afterEach(async()=>{await Promise.allSettled([...pendingWork]);for(const c of children.splice(0))if(c.exitCode===null&&c.signalCode===null)c.kill('SIGKILL');await Promise.all(servers.splice(0).map(s=>new Promise<void>(r=>{s.close(()=>r());s.closeAllConnections();})));vi.restoreAllMocks();});
afterAll(async()=>{await Promise.all([provider,catalog].filter(Boolean).map(s=>new Promise<void>(r=>{s.close(()=>r());s.closeAllConnections();})));await mockPool?.end();if(mockSchema)await mockAdmin.query(`DROP SCHEMA "${mockSchema}" CASCADE`);await mockAdmin?.end();await Promise.all([orders?.close(),inventory?.close(),payments?.close()]);});
const adminId=randomUUID();
const adminToken=`Bearer ${await jwt.sign('admin',{sub:adminId})}`;
const refundInput=(paymentId:string,amountPaise=125)=>({paymentId,amountPaise,currency:'INR' as const,reason:'ADMIN_REQUEST' as const});
function captured(){return tracked((async()=>{const o=await create();await reserve();await pay();await finish();return {order:o,paymentId:(await row()).payment_id!};})());}
async function issueRefund(paymentId:string,amount=125,key=randomUUID()){return tracked(refundRepo.create(adminId,key,refundInput(paymentId,amount)));}
const providerRefunds=async()=>(await mockPool.query('SELECT * FROM mock_refunds')).rows;
async function refundOutcomes(){for(const e of await events(payments))if(e.eventType.startsWith('payment.refund_'))await saga.refundHandler(e,context);}
async function refundCancellation(){await refundConsumer(await command('payment.refund.requested'),context);await refundService.runOnce();await refundOutcomes();}
async function compensateCancellation(){await compensate(await command('inventory.compensate.requested'),context);for(const e of await events(inventory,'checkout.inventory.compensated'))await saga.handler(e,context);}
async function makeDue(){await payments.pool.query("UPDATE refunds SET next_action_at=clock_timestamp(),lease_expires_at=CASE WHEN lease_token IS NOT NULL THEN clock_timestamp()-INTERVAL '1 second' ELSE NULL END");}
const pendingWork=new Set<Promise<unknown>>();
function tracked<T>(work:Promise<T>){pendingWork.add(work);void work.then(()=>pendingWork.delete(work),()=>pendingWork.delete(work));return work;}
function deliveryService(...args:ConstructorParameters<typeof RefundService>){
 const service=new RefundService(...args),once=service.runOnce.bind(service),execute=service.execute.bind(service),reconcile=service.reconcile.bind(service);
 service.runOnce=(...params)=>tracked(once(...params));service.execute=(...params)=>tracked(execute(...params));service.reconcile=(...params)=>tracked(reconcile(...params));return service;
}
const paymentApi=()=>paymentsApp(paymentService,jwt.verify,()=> 'ready',refundService);
describe('Refund amount reservation and provider idempotency',()=>{
 it('refunds a captured payment in full and commits its outcome outbox atomically',async()=>{const {paymentId}=await captured();const r=await issueRefund(paymentId);expect(r.status).toBe('REQUESTED');await refundService.runOnce();expect((await refundRepo.get(r.id)).status).toBe('SUCCEEDED');expect(await providerRefunds()).toHaveLength(1);expect(await events(payments,'payment.refund_succeeded')).toHaveLength(1);expect((await payments.pool.query('SELECT * FROM refund_attempts')).rows).toHaveLength(1);});
 it('supports several partial refunds whose sum equals captured amount',async()=>{const {paymentId}=await captured();await issueRefund(paymentId,40);await issueRefund(paymentId,30);await issueRefund(paymentId,55);await refundService.runOnce();expect((await providerRefunds()).reduce((n,r)=>n+BigInt(r.amount_paise),0n)).toBe(125n);await expect(issueRefund(paymentId,1)).rejects.toThrow('balance');});
 it('includes requested, processing, unknown and manual-review refunds in capacity',async()=>{const {paymentId}=await captured();scenario='ambiguous';const r=await issueRefund(paymentId,100);await expect(issueRefund(paymentId,26)).rejects.toThrow();const claim=await refundRepo.claim(r.id);await expect(issueRefund(paymentId,26)).rejects.toThrow();await refundService.execute(claim!);await expect(issueRefund(paymentId,26)).rejects.toThrow();await payments.pool.query("UPDATE refunds SET status='MANUAL_REVIEW_REQUIRED',next_action_at=NULL WHERE id=$1",[r.id]);await expect(issueRefund(paymentId,26)).rejects.toThrow();expect((await refundRepo.get(r.id)).status).toBe('MANUAL_REVIEW_REQUIRED');});
 it('serializes concurrent refund requests on captured payment balance',async()=>{const {paymentId}=await captured();const results=await Promise.allSettled(Array.from({length:12},()=>issueRefund(paymentId,25)));expect(results.filter(r=>r.status==='fulfilled')).toHaveLength(5);expect((await payments.pool.query('SELECT SUM(amount_paise)::text AS total FROM refunds')).rows[0].total).toBe('125');await refundService.runOnce();expect(await providerRefunds()).toHaveLength(5);});
 it('deduplicates concurrent identical keys and rejects conflicting retries',async()=>{const {paymentId}=await captured(),key=randomUUID();const requests=await Promise.all(Array.from({length:8},()=>issueRefund(paymentId,40,key)));expect(new Set(requests.map(r=>r.id)).size).toBe(1);await expect(issueRefund(paymentId,41,key)).rejects.toThrow('conflicts');await Promise.all([refundService.runOnce(),refundService.runOnce()]);expect(await providerRefunds()).toHaveLength(1);});
 it('rejects non-captured payments, mismatched currencies, zero, fractional and excessive amounts',async()=>{await create();await reserve();await paymentHandler(await command('payment.process.requested'),context);const id=(await payments.pool.query('SELECT id FROM payments')).rows[0].id;await expect(issueRefund(id)).rejects.toThrow('not refundable');await pay();for(const amount of [0,-1,1.5,126,Number.MAX_SAFE_INTEGER+1])await expect(issueRefund(id,amount)).rejects.toThrow();await expect(refundRepo.create(adminId,randomUUID(),{...refundInput(id),currency:'USD' as never})).rejects.toThrow();});
 it('releases refund capacity only after definitive provider decline',async()=>{const {paymentId}=await captured();scenario='decline';const r=await issueRefund(paymentId);await refundService.runOnce();expect((await refundRepo.get(r.id)).status).toBe('FAILED');scenario='success';await issueRefund(paymentId);await refundService.runOnce();expect((await providerRefunds()).filter(r=>r.status==='SUCCEEDED')).toHaveLength(1);});
 it.each(['lost-response','timeout'] as const)('reconciles %s using the same operation without another refund',async mode=>{const {paymentId}=await captured();scenario=mode;refundService=deliveryService(refundRepo,new ProviderClient(providerUrl,20));const r=await issueRefund(paymentId);await refundService.runOnce();expect((await refundRepo.get(r.id)).status).toBe('REQUIRES_RECONCILIATION');await vi.waitFor(async()=>expect(await providerRefunds()).toHaveLength(1));const recovery=deliveryService(refundRepo,new ProviderClient(providerUrl,1000));const result=await recovery.reconcile(r.id);expect(result.status).toBe('SUCCEEDED');expect(await providerRefunds()).toHaveLength(1);expect((await providerRefunds())[0].operation_id).toBe(r.provider_operation_id);});
 it('keeps permanently unknown refunds reserved and escalates without assuming failure',async()=>{const {paymentId}=await captured();scenario='ambiguous';const r=await issueRefund(paymentId);for(let i=0;i<8;i++){await makeDue();await refundService.runOnce();}expect((await refundRepo.get(r.id)).status).toBe('MANUAL_REVIEW_REQUIRED');await expect(issueRefund(paymentId,1)).rejects.toThrow();expect(await providerRefunds()).toHaveLength(1);expect((await payments.pool.query('SELECT next_action_at FROM refunds')).rows[0].next_action_at).toBeNull();});
 it('reconciles a definitive failure and allows new capacity without retrying the old operation',async()=>{const {paymentId}=await captured();scenario='ambiguous';const r=await issueRefund(paymentId);await refundService.runOnce();await mockPool.query("UPDATE mock_refunds SET status='FAILED',failure_code='PROVIDER_DECLINED' WHERE operation_id=$1",[r.provider_operation_id]);expect((await refundService.reconcile(r.id)).status).toBe('FAILED');await issueRefund(paymentId);expect((await refundRepo.get(r.id)).status).toBe('FAILED');});
 it('fences stale lease responses and never rewrites definitive success',async()=>{const {paymentId}=await captured();const r=await issueRefund(paymentId),old=await refundRepo.claim(r.id);await payments.pool.query("UPDATE refunds SET lease_expires_at=clock_timestamp()-INTERVAL '1 second'");const next=await refundRepo.claim(r.id);await refundRepo.finish(r.id,next!.token,{status:'SUCCEEDED',providerRefundId:randomUUID()});await refundRepo.finish(r.id,old!.token,{status:'FAILED',failureCode:'PROVIDER_DECLINED'});expect((await refundRepo.get(r.id)).status).toBe('SUCCEEDED');expect(await events(payments,'payment.refund_succeeded')).toHaveLength(1);});
 it('provider itself deduplicates concurrent refund calls and protects captured balance',async()=>{const {paymentId}=await captured();const client=new ProviderClient(providerUrl,1000),operation=randomUUID();await Promise.all(Array.from({length:8},()=>client.refundPayment(operation,paymentId,100,'INR')));expect(await providerRefunds()).toHaveLength(1);expect((await client.refundPayment(randomUUID(),paymentId,26,'INR')).status).toBe('FAILED');expect((await client.getRefundStatus(operation)).status).toBe('SUCCEEDED');});
 it('restores provider lookup after a provider app restart using persisted state',async()=>{const {paymentId}=await captured();const r=await issueRefund(paymentId);scenario='lost-response';await refundService.runOnce();const restarted=createServer(createMockProvider(mockPool,()=> 'success'));servers.push(restarted);await new Promise<void>(resolve=>restarted.listen(0,'127.0.0.1',resolve));const origin=`http://127.0.0.1:${(restarted.address() as AddressInfo).port}`;expect((await deliveryService(refundRepo,new ProviderClient(origin,1000)).reconcile(r.id)).status).toBe('SUCCEEDED');expect(await providerRefunds()).toHaveLength(1);});
});
describe('Cancellation coordinates payment, refunds and inventory in the checkout Saga',()=>{
 it('cancels before reservation with no payment initiation and waits for release',async()=>{const o=await create();await saga.cancel(userId,false,o.id,'cancel');expect((await row()).state).toBe('CANCELLATION_PENDING');await inventoryHandler(await command('inventory.reserve.requested'),context);await saga.handler((await events(inventory,'checkout.inventory.reserved'))[0]!,context);expect(await events(orders,'payment.process.requested')).toHaveLength(0);expect((await row()).state).toBe('INVENTORY_RELEASE_PENDING');await compensateCancellation();expect((await row()).state).toBe('CANCELLED');expect(await stock.find(productId)).toMatchObject({totalStock:5,reservedStock:0});});
 it('cancels an inventory failure without charging or inventing a reservation',async()=>{await stock.put(productId,0);const o=await create();await saga.cancel(userId,false,o.id,'cancel');await inventoryHandler(await command('inventory.reserve.requested'),context);await saga.handler((await events(inventory,'checkout.inventory.reservation_failed'))[0]!,context);expect((await row()).state).toBe('CANCELLED');expect(await events(orders,'payment.process.requested')).toHaveLength(0);});
 it('waits for a delayed payment command rather than assuming it was never accepted',async()=>{const o=await create();await reserve();await saga.cancel(userId,false,o.id,'cancel');expect((await row()).state).toBe('CANCELLATION_PENDING');await pay();expect((await row()).state).toBe('REFUND_PENDING');expect(await events(orders,'inventory.confirm.requested')).toHaveLength(0);await refundCancellation();await compensateCancellation();expect((await row()).state).toBe('CANCELLED');expect(await charges()).toHaveLength(1);expect(await providerRefunds()).toHaveLength(1);});
 it('releases on definitive payment failure without a refund',async()=>{scenario='decline';const o=await create();await reserve();await saga.cancel(userId,false,o.id,'cancel');await pay();expect((await row()).state).toBe('INVENTORY_RELEASE_PENDING');await compensateCancellation();expect((await row()).state).toBe('CANCELLED');expect(await providerRefunds()).toHaveLength(0);});
 it('keeps ambiguous payments protected during cancellation then refunds delayed success',async()=>{scenario='lost-response';const o=await create();await reserve();await pay();await saga.cancel(userId,false,o.id,'cancel');expect((await row()).state).toBe('CANCELLATION_PENDING');await paymentService.reconcileBatch(10);for(const e of await events(payments))if(e.eventType.startsWith('checkout.'))await saga.handler(e,context);expect((await row()).state).toBe('REFUND_PENDING');scenario='success';await refundCancellation();await compensateCancellation();expect((await row()).state).toBe('CANCELLED');});
 it('restores confirmed stock exactly once only after a successful full cancellation refund',async()=>{const {order}=await captured();await saga.cancel(userId,false,order.id,'cancel');expect(await stock.find(productId)).toMatchObject({totalStock:4});await refundCancellation();expect((await row()).state).toBe('INVENTORY_RELEASE_PENDING');await compensateCancellation();expect((await row()).state).toBe('CANCELLED');expect((await orders.pool.query('SELECT status FROM orders')).rows[0].status).toBe('CANCELLED');expect(await stock.find(productId)).toMatchObject({totalStock:5,reservedStock:0});const original=await command('inventory.compensate.requested');await Promise.all([compensate(original,context),compensate(sagaEvent(original.eventType,original.payload as never,keys,original.correlationId,original),context)]);expect(await stock.find(productId)).toMatchObject({totalStock:5});expect((await inventory.pool.query('SELECT * FROM inventory_compensations')).rowCount).toBe(1);});
 it('blocks stale confirmation after compensation and does not restore an unrelated order',async()=>{const {order}=await captured();const oldConfirm=await command('inventory.confirm.requested');await saga.cancel(userId,false,order.id,'cancel');await refundCancellation();await compensateCancellation();const replay=sagaEvent(oldConfirm.eventType,oldConfirm.payload as never,keys,oldConfirm.correlationId,oldConfirm);await inventoryHandler(replay,context);expect(await stock.find(productId)).toMatchObject({totalStock:5});const cmd=await command('inventory.compensate.requested');if(cmd.eventType!=='inventory.compensate.requested')throw new Error();await expect(compensate(sagaEvent(cmd.eventType,{...cmd.payload,orderId:randomUUID()},keys,cmd.correlationId),context)).rejects.toThrow();expect(await stock.find(productId)).toMatchObject({totalStock:5});});
 it('deduplicates concurrent cancellation keys and rejects conflicting reuse across orders',async()=>{const o=await create();const requests=await Promise.all(Array.from({length:8},()=>saga.cancel(userId,false,o.id,'same-key')));expect(new Set(requests.map(r=>r.sagaId)).size).toBe(1);await saga.cancel(userId,false,o.id,'second-key');expect((await orders.pool.query("SELECT * FROM checkout_saga_transitions WHERE to_state='CANCELLATION_REQUESTED'")).rowCount).toBe(1);const other=await create();await expect(saga.cancel(userId,false,other.id,'same-key')).rejects.toThrow('conflicts');});
 it('blocks completed cancellation on definitive refund failure, preserving financial and inventory state',async()=>{const {order}=await captured();await saga.cancel(userId,false,order.id,'cancel');scenario='decline';await refundCancellation();expect((await row()).state).toBe('CANCELLATION_FAILED');expect((await orders.pool.query('SELECT status FROM orders')).rows[0].status).toBe('CONFIRMED');expect(await stock.find(productId)).toMatchObject({totalStock:4});expect(await events(orders,'inventory.compensate.requested')).toHaveLength(0);});
 it('blocks cancellation on unknown refund and resumes on definitive reconciliation',async()=>{const {order}=await captured();await saga.cancel(userId,false,order.id,'cancel');scenario='lost-response';await refundCancellation();expect((await row()).state).toBe('REFUND_RECONCILIATION_REQUIRED');expect(await stock.find(productId)).toMatchObject({totalStock:4});const r=(await payments.pool.query('SELECT id FROM refunds')).rows[0];await refundService.reconcile(r.id);await refundOutcomes();await compensateCancellation();expect((await row()).state).toBe('CANCELLED');expect(await providerRefunds()).toHaveLength(1);});
 it('automatically compensates paid but durably impossible fulfillment, not delayed confirmation',async()=>{await create();await reserve();await pay();expect((await row()).state).toBe('INVENTORY_CONFIRMATION_PENDING');expect(await events(orders,'payment.refund.requested')).toHaveLength(0);await inventory.pool.query("UPDATE inventory_reservations SET status='RELEASED' WHERE order_id=$1",[(await row()).order_id]);await inventory.pool.query('UPDATE inventory SET reserved_stock=0');await inventoryHandler(await command('inventory.confirm.requested'),context);const impossible=(await events(inventory,'checkout.inventory.fulfillment_impossible'))[0]!;expect(impossible).toBeDefined();await saga.handler(impossible,context);expect((await row()).state).toBe('REFUND_PENDING');await refundCancellation();await compensateCancellation();expect((await row()).state).toBe('COMPENSATED');expect((await orders.pool.query('SELECT status FROM orders')).rows[0].status).toBe('FAILED');expect(await stock.find(productId)).toMatchObject({totalStock:5,reservedStock:0});});
 it('retains manual review for unknown fulfillment without automatically refunding',async()=>{await create();await reserve();await pay();const s=await row();await saga.handler(sagaEvent('checkout.inventory.confirmation_failed',{...link(s),reservationId:s.reservation_operation_id,reason:'INVALID_RESERVATION'},keys,s.correlation_id),context);expect((await row()).state).toBe('MANUAL_REVIEW_REQUIRED');expect(await events(orders,'payment.refund.requested')).toHaveLength(0);});
 it('handles duplicate and out-of-order refund outcomes without repeating compensation',async()=>{const {order}=await captured();await saga.cancel(userId,false,order.id,'cancel');await refundCancellation();const success=(await events(payments,'payment.refund_succeeded'))[0]!;await Promise.all([saga.refundHandler(success,context),saga.refundHandler(success,context)]);if(success.eventType!=='payment.refund_succeeded')throw new Error();await saga.refundHandler(sagaEvent('payment.refund_failed',{...success.payload,failureCode:'PROVIDER_DECLINED'},keys,success.correlationId),context);await compensateCancellation();expect((await row()).state).toBe('CANCELLED');expect(await events(orders,'inventory.compensate.requested')).toHaveLength(1);});
 it('validates refund linkage and amount before accepting outcome events',async()=>{const {order}=await captured();await saga.cancel(userId,false,order.id,'cancel');const s=await row(),p={refundId:s.refund_operation_id!,paymentId:s.payment_id!,orderId:s.order_id,userId,refundOperationId:s.refund_operation_id!,amountPaise:1,currency:'INR' as const,reason:'CUSTOMER_CANCELLATION' as const,sagaId:s.id};await expect(saga.refundHandler(sagaEvent('payment.refund_succeeded',p,keys,s.correlation_id),context)).rejects.toThrow();expect((await row()).state).toBe('REFUND_PENDING');});
 it('does not automatically issue a second full refund when prior partials consumed capacity',async()=>{const {order,paymentId}=await captured();await issueRefund(paymentId,40);await refundService.runOnce();await saga.cancel(userId,false,order.id,'cancel');await refundCancellation();expect((await row()).state).toBe('CANCELLATION_FAILED');expect((await providerRefunds()).reduce((n,r)=>n+Number(r.amount_paise),0)).toBe(40);expect(await stock.find(productId)).toMatchObject({totalStock:4});});
 it('allows existing recovery to resume cancellation with stable operation IDs',async()=>{const o=await create();await saga.cancel(userId,false,o.id,'cancel');await orders.pool.query('UPDATE checkout_sagas SET next_action_at=clock_timestamp()');await Promise.all([saga.recover(),saga.recover()]);await inventoryHandler(await command('inventory.reserve.requested'),context);await saga.handler((await events(inventory,'checkout.inventory.reserved'))[0]!,context);const original=await command('inventory.compensate.requested');await orders.pool.query('UPDATE checkout_sagas SET next_action_at=clock_timestamp()');await saga.recover();expect((await command('inventory.compensate.requested')).payload).toEqual(original.payload);await compensateCancellation();expect((await row()).state).toBe('CANCELLED');});
});
describe('Refund and cancellation API security',()=>{
 it('requires admin creation and reconciliation, and limits refund visibility to owner or admin',async()=>{const {paymentId}=await captured(),api=paymentApi();await request(api).post(`/payments/${paymentId}/refunds`).send({amountPaise:40,currency:'INR'}).expect(401);await request(api).post(`/payments/${paymentId}/refunds`).set('authorization',token).set('idempotency-key','customer-refund').send({amountPaise:40,currency:'INR'}).expect(403);const created=await request(api).post(`/payments/${paymentId}/refunds`).set('authorization',adminToken).set('idempotency-key','admin-refund').send({amountPaise:40,currency:'INR'}).expect(202);const id=created.body.refundId;const other=`Bearer ${await jwt.sign('customer',{sub:randomUUID()})}`;await request(api).get(`/payments/refunds/${id}`).set('authorization',other).expect(404);await request(api).get(`/payments/${paymentId}/refunds`).set('authorization',other).expect(404);await request(api).get(`/payments/refunds/${id}`).set('authorization',token).expect(200);await request(api).post(`/payments/refunds/${id}/reconcile`).set('authorization',token).send({}).expect(403);await request(api).post(`/payments/refunds/${id}/reconcile`).set('authorization',adminToken).send({}).expect(409);expect(created.body).not.toHaveProperty('provider_operation_id');});
 it('returns 409 on conflicting admin idempotency and rejects arbitrary reason or extra fields',async()=>{const {paymentId}=await captured(),api=paymentApi();await request(api).post(`/payments/${paymentId}/refunds`).set('authorization',adminToken).set('idempotency-key','admin-refund').send({amountPaise:40,currency:'INR'}).expect(202);await request(api).post(`/payments/${paymentId}/refunds`).set('authorization',adminToken).set('idempotency-key','admin-refund').send({amountPaise:41,currency:'INR'}).expect(409);await request(api).post(`/payments/${paymentId}/refunds`).set('authorization',adminToken).set('idempotency-key','bad').send({amountPaise:10,currency:'INR',reason:'CUSTOMER_CANCELLATION'}).expect(400);});
 it('enforces cancellation ownership, allows admin cancellation, and rejects customer amounts',async()=>{const {order}=await captured(),api=app(),other=`Bearer ${await jwt.sign('customer',{sub:randomUUID()})}`;await request(api).post(`/orders/${order.id}/cancel`).send({}).expect(401);await request(api).post(`/orders/${order.id}/cancel`).set('authorization',other).set('idempotency-key','other').send({}).expect(404);await request(api).post(`/orders/${order.id}/cancel`).set('authorization',token).set('idempotency-key','amount').send({amountPaise:1}).expect(400);await request(api).post(`/orders/${order.id}/cancel`).set('authorization',adminToken).set('idempotency-key','admin-cancel').send({}).expect(202);await request(api).get(`/orders/${order.id}/cancellation`).set('authorization',other).expect(404);await request(api).get(`/orders/${order.id}/refunds`).set('authorization',other).expect(404);await request(api).get(`/orders/${order.id}/cancellation`).set('authorization',token).expect(200);});
 it('rejects unsigned commands and mismatched refund operations transactionally',async()=>{const {order}=await captured();await saga.cancel(userId,false,order.id,'cancel');const cmd=await command('payment.refund.requested');await expect(refundConsumer({...cmd,signature:undefined},context)).rejects.toThrow();if(cmd.eventType!=='payment.refund.requested')throw new Error();await expect(refundConsumer(sagaEvent(cmd.eventType,{...cmd.payload,paymentOperationId:randomUUID()},keys,cmd.correlationId),context)).rejects.toThrow();expect((await payments.pool.query('SELECT * FROM refunds')).rowCount).toBe(0);await refundConsumer(cmd,context);await expect(refundConsumer(sagaEvent(cmd.eventType,{...cmd.payload,userId:randomUUID()},keys,cmd.correlationId),context)).rejects.toThrow();expect((await payments.pool.query('SELECT * FROM refunds')).rowCount).toBe(1);});
 it('forwards cancellation and refund endpoints through Gateway with exact authorization and statuses',async()=>{const {order,paymentId}=await captured();const orderServer=createServer(app()),payServer=createServer(paymentApi());servers.push(orderServer,payServer);await Promise.all([orderServer,payServer].map(server=>new Promise<void>(r=>server.listen(0,'127.0.0.1',r))));const gateway=gatewayApp({CATALOG_SERVICE_URL:catalogUrl,CATALOG_REQUEST_TIMEOUT_MS:1000,ORDERS_SERVICE_URL:`http://127.0.0.1:${(orderServer.address() as AddressInfo).port}`,PAYMENTS_SERVICE_URL:`http://127.0.0.1:${(payServer.address() as AddressInfo).port}`});await request(gateway).post(`/payments/${paymentId}/refunds`).set('authorization',adminToken).set('idempotency-key','gateway-refund').send({amountPaise:20,currency:'INR'}).expect(202);await request(gateway).get(`/payments/${paymentId}/refunds`).set('authorization',token).expect(200);await request(gateway).post(`/orders/${order.id}/cancel`).set('authorization',token).set('idempotency-key','gateway-cancel').send({}).expect(202);await request(gateway).get(`/orders/${order.id}/cancellation`).set('authorization',token).expect(200);await request(gateway).get(`/orders/${order.id}/refunds`).set('authorization',token).expect(200);});
 it('lists standalone admin partial refund outcomes for the owning order without automatic stock changes',async()=>{const {order,paymentId}=await captured();await issueRefund(paymentId,40);await refundService.runOnce();await refundOutcomes();expect(await saga.refunds(userId,false,order.id)).toMatchObject([{amountPaise:40,status:'SUCCEEDED'}]);expect((await row()).state).toBe('COMPLETED');expect(await stock.find(productId)).toMatchObject({totalStock:4});});
});
describe('Real process crashes and persistent financial recovery',()=>{
 it.each(['before','after'] as const)('recovers a refund intent crash %s commit',async position=>{const {paymentId}=await captured(),key='crash-intent',input=refundInput(paymentId);await crash(`refund-${position}-intent-commit`,payments,{TEST_PRINCIPAL:adminId,TEST_KEY:key,TEST_INPUT:JSON.stringify(input)});expect((await payments.pool.query('SELECT * FROM refunds')).rowCount).toBe(position==='before'?0:1);const r=await refundRepo.create(adminId,key,input);await refundService.runOnce();expect((await refundRepo.get(r.id)).status).toBe('SUCCEEDED');expect(await providerRefunds()).toHaveLength(1);});
 it.each(['refund-after-provider','refund-before-outcome-commit','refund-after-outcome-commit'])('recovers %s from the original durable provider operation',async mode=>{const {paymentId}=await captured();const r=await issueRefund(paymentId);await crash(mode,payments);expect(await providerRefunds()).toHaveLength(1);await makeDue();await deliveryService(new RefundRepository(payments.pool,keys,100,10),new ProviderClient(providerUrl,1000)).runOnce();expect((await refundRepo.get(r.id)).status).toBe('SUCCEEDED');expect(await providerRefunds()).toHaveLength(1);expect(await events(payments,'payment.refund_succeeded')).toHaveLength(1);});
 it('recovers refund acceptance committed before consumer ACK',async()=>{const {order}=await captured();await saga.cancel(userId,false,order.id,'cancel');const cmd=await command('payment.refund.requested');await crash('refund-consumer-after-commit',payments,{TEST_EVENT:JSON.stringify(cmd)});await refundConsumer(cmd,context);await refundService.runOnce();expect((await payments.pool.query('SELECT * FROM refunds')).rowCount).toBe(1);expect(await providerRefunds()).toHaveLength(1);});
 it('recovers Orders refund outcome committed before ACK without another compensation command',async()=>{const {order}=await captured();await saga.cancel(userId,false,order.id,'cancel');await refundConsumer(await command('payment.refund.requested'),context);await refundService.runOnce();const outcome=(await events(payments,'payment.refund_succeeded'))[0]!;await crash('orders-refund-after-commit',orders,{TEST_EVENT:JSON.stringify(outcome)});await saga.refundHandler(outcome,context);expect(await events(orders,'inventory.compensate.requested')).toHaveLength(1);await compensateCancellation();expect((await row()).state).toBe('CANCELLED');});
 it.each(['before','after'] as const)('recovers Inventory compensation crash %s commit without double stock restoration',async position=>{const {order}=await captured();await saga.cancel(userId,false,order.id,'cancel');await refundCancellation();const cmd=await command('inventory.compensate.requested');await crash(`inventory-${position}-commit`,inventory,{TEST_EVENT:JSON.stringify(cmd)});expect(await stock.find(productId)).toMatchObject({totalStock:position==='before'?4:5});await compensateCancellation();expect(await stock.find(productId)).toMatchObject({totalStock:5});expect((await inventory.pool.query('SELECT * FROM inventory_compensations')).rowCount).toBe(1);});
 it('recovers cancellation committed before Orders restart and a crashed recovery claim',async()=>{const {order}=await captured();await crash('orders-cancel-after-commit',orders,{TEST_ORDER:order.id});expect((await row()).state).toBe('REFUND_PENDING');await orders.pool.query('UPDATE checkout_sagas SET next_action_at=clock_timestamp()');await crash('orders-after-claim',orders);await orders.pool.query("UPDATE checkout_sagas SET locked_until=clock_timestamp()-INTERVAL '1 second'");await saga.recover();await refundCancellation();await compensateCancellation();expect((await row()).state).toBe('CANCELLED');expect(await providerRefunds()).toHaveLength(1);});
 it('preserves a durable provider refund when PostgreSQL outcome persistence fails and recovers by lookup',async()=>{const {paymentId}=await captured();const r=await issueRefund(paymentId);await payments.pool.query(`CREATE FUNCTION fail_refund_result() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status='SUCCEEDED' THEN RAISE EXCEPTION 'Injected PostgreSQL outcome failure'; END IF; RETURN NEW; END $$`);await payments.pool.query('CREATE TRIGGER fail_refund_result BEFORE UPDATE ON refunds FOR EACH ROW EXECUTE FUNCTION fail_refund_result()');try{await expect(refundService.runOnce()).rejects.toThrow();expect((await refundRepo.get(r.id)).status).toBe('PROCESSING');expect(await providerRefunds()).toHaveLength(1);expect(await events(payments,'payment.refund_succeeded')).toHaveLength(0);}finally{await payments.pool.query('DROP TRIGGER fail_refund_result ON refunds');await payments.pool.query('DROP FUNCTION fail_refund_result()');}await makeDue();await refundService.runOnce();expect((await refundRepo.get(r.id)).status).toBe('SUCCEEDED');expect(await providerRefunds()).toHaveLength(1);});
 it('recovers a disconnected database client during reconciliation without losing reserved capacity',async()=>{const {paymentId}=await captured();scenario='lost-response';const r=await issueRefund(paymentId);await refundService.runOnce();const disconnected=new Pool({...payments.config,options:`-c search_path=${payments.schema}`});const client=await disconnected.connect();client.on('error',()=>{});await client.query('SELECT pg_terminate_backend(pg_backend_pid())').catch(()=>{});client.release(true);const restart=deliveryService(new RefundRepository(disconnected,keys,100,10),new ProviderClient(providerUrl,1000));try{expect((await restart.reconcile(r.id)).status).toBe('SUCCEEDED');expect(await providerRefunds()).toHaveLength(1);}finally{await disconnected.end();}});
});
describe('RabbitMQ distributed refund and compensation',()=>{
 it('recovers publisher outage, duplicate outcomes and consumer-before-ACK failure end to end',async()=>{
  const {order}=await captured();await saga.cancel(userId,false,order.id,'cancel');const ns=`test_${randomUUID().replaceAll('-','')}`;
  const selected=['inventory.order-created.v1','payments.order-created.v1','inventory.checkout-commands.v1','payments.checkout-commands.v1','orders.checkout-events.v1','payments.refund-commands.v1','inventory.compensation-commands.v1','orders.refund-events.v1'] as const;
  const settings={url:rabbitUrl,namespace:ns,queues:[...selected],retryDelays:[100,150,200],reconnectBaseMs:50,reconnectMaxMs:500,confirmTimeoutMs:2000,shutdownTimeoutMs:1000};
  const manager=new Messaging(settings,['orders','inventory','payments'],()=>{});let beforeAck=true;
  manager.register('payments.refund-commands.v1',refundConsumer);manager.register('inventory.compensation-commands.v1',compensate);manager.register('orders.checkout-events.v1',saga.handler);manager.register('orders.refund-events.v1',async(e,c)=>{await saga.refundHandler(e,c);if(beforeAck){beforeAck=false;throw new Error('Injected ACK window');}});
  const workers=[orders,inventory,payments].map(db=>new OutboxWorker(new OutboxRepository(db.pool),manager,{},()=>{},Date.now,()=>0));const offline=new Messaging({...settings,url:'amqp://unavailable:password@127.0.0.1:1/commerce_test'},['orders'],()=>{});
  try{
   offline.start();await new OutboxWorker(new OutboxRepository(orders.pool),offline,{},()=>{},Date.now,()=>0).runOnce();expect((await orders.pool.query("SELECT status FROM outbox_events WHERE event_type='payment.refund.requested'")).rows[0].status).toBe('PENDING');
   manager.start();await vi.waitFor(()=>expect(manager.status,JSON.stringify({status:manager.status,counters:manager.counters})).toBe('ready'),{timeout:20000});await vi.waitFor(async()=>{for(const w of workers)await w.runOnce();await refundService.runOnce();expect((await row(order.id)).state).toBe('CANCELLED');},{timeout:20000,interval:100});
   const success=(await events(payments,'payment.refund_succeeded'))[0]!;await manager.publish(success);await manager.publish(await command('payment.refund.requested'));await vi.waitFor(()=>expect(manager.counters.retried).toBeGreaterThan(0));expect(await providerRefunds()).toHaveLength(1);expect(await stock.find(productId)).toMatchObject({totalStock:5});expect((await inventory.pool.query('SELECT * FROM inventory_compensations')).rowCount).toBe(1);
  }finally{await Promise.all(workers.map(w=>w.stop()));await offline.stop();await manager.stop();const conn=await amqp.connect(rabbitUrl),ch=await conn.createChannel();for(const spec of queueSpecs.filter(s=>settings.queues.some(name=>name===s.name))){const n=names(ns,spec);for(const q of [n.queue,n.dlq,...[1,2,3].map(i=>`${n.queue}.retry.${i}`)])await ch.deleteQueue(q);}for(const service of ['orders','inventory','payments'])await ch.deleteExchange(`${ns}.commerce.${service}.handoff`);await ch.deleteExchange(`${ns}.commerce.events`);await ch.close();await conn.close();}
 });
});
describe('Operator resolution and inventory lifecycle distinctions',()=>{
 it('allows an operator to resolve manual refund review by lookup and resumes cancellation safely',async()=>{const {order}=await captured();await saga.cancel(userId,false,order.id,'cancel');scenario='ambiguous';await refundCancellation();const r=(await payments.pool.query('SELECT * FROM refunds')).rows[0];for(let i=1;i<8;i++){await makeDue();await refundService.runOnce();}await refundOutcomes();expect((await row()).state).toBe('MANUAL_REVIEW_REQUIRED');expect((await refundRepo.get(r.id)).status).toBe('MANUAL_REVIEW_REQUIRED');await mockPool.query("UPDATE mock_refunds SET status='SUCCEEDED',provider_refund_id=$2 WHERE operation_id=$1",[r.provider_operation_id,randomUUID()]);expect((await refundService.reconcile(r.id)).status).toBe('SUCCEEDED');await refundOutcomes();await compensateCancellation();expect((await row()).state).toBe('CANCELLED');expect(await providerRefunds()).toHaveLength(1);});
 it('keeps temporary provider failure unknown until a definitive persisted lookup result exists',async()=>{const {paymentId}=await captured();scenario='temporary-failure';const r=await issueRefund(paymentId);await refundService.runOnce();expect((await refundRepo.get(r.id)).status).toBe('REQUIRES_RECONCILIATION');await expect(issueRefund(paymentId,1)).rejects.toThrow();await mockPool.query("UPDATE mock_refunds SET status='SUCCEEDED',provider_refund_id=$2 WHERE operation_id=$1",[r.provider_operation_id,randomUUID()]);expect((await refundService.reconcile(r.id)).status).toBe('SUCCEEDED');expect(await providerRefunds()).toHaveLength(1);});
 it('classifies already expired reservations without decrementing stock a second time',async()=>{const o=await create();await saga.cancel(userId,false,o.id,'cancel');await inventoryHandler(await command('inventory.reserve.requested'),context);await saga.handler((await events(inventory,'checkout.inventory.reserved'))[0]!,context);await inventory.pool.query("UPDATE inventory_reservations SET status='EXPIRED' WHERE order_id=$1",[o.id]);await inventory.pool.query('UPDATE inventory SET reserved_stock=0');await compensateCancellation();expect((await inventory.pool.query('SELECT result FROM inventory_compensations')).rows[0].result).toBe('ALREADY_EXPIRED');expect(await stock.find(productId)).toMatchObject({totalStock:5,reservedStock:0});expect((await row()).state).toBe('CANCELLED');});
 it('rejects restoration of confirmed stock without a successful refund operation',async()=>{await captured();const s=await row();await expect(compensate(sagaEvent('inventory.compensate.requested',{...link(s),reservationId:s.reservation_operation_id,compensationOperationId:randomUUID(),refundOperationId:null},keys,s.correlation_id),context)).rejects.toThrow();expect(await stock.find(productId)).toMatchObject({totalStock:4});expect((await inventory.pool.query('SELECT * FROM inventory_compensations')).rowCount).toBe(0);});
 it.each(['decline','ambiguous'] as const)('keeps paid-but-unfulfilled compensation recoverable on refund %s',async mode=>{await create();await reserve();await pay();const s=await row();await saga.handler(sagaEvent('checkout.inventory.fulfillment_impossible',{...link(s),reservationId:s.reservation_operation_id,reason:'RELEASED'},keys,s.correlation_id),context);scenario=mode;await refundCancellation();expect((await row()).state).toBe(mode==='decline'?'CANCELLATION_FAILED':'REFUND_RECONCILIATION_REQUIRED');expect((await orders.pool.query('SELECT status FROM orders')).rows[0].status).toBe('PENDING');expect(await events(orders,'inventory.compensate.requested')).toHaveLength(0);});
 it('keeps new refund and cancellation operations disabled when no opt-in services are supplied',async()=>{const o=await create();const disabled=createApp(new OrderService(new OrderRepository(orders.pool),new CartClient(catalogUrl,1000),new CatalogClient(catalogUrl,1000)),jwt.verify,()=> 'ready',{repository:saga,keys});await request(disabled).post(`/orders/${o.id}/cancel`).set('authorization',token).set('idempotency-key','disabled').send({}).expect(503);await reserve();await pay();await finish();const paymentId=(await row()).payment_id!;await request(paymentsApp(paymentService,jwt.verify)).post(`/payments/${paymentId}/refunds`).set('authorization',adminToken).set('idempotency-key','disabled').send({amountPaise:125,currency:'INR'}).expect(503);expect((await payments.pool.query('SELECT * FROM refunds')).rowCount).toBe(0);});
});
describe('Database disconnection during refund reconciliation persistence',()=>{
 it('rolls back an interrupted result transaction and recovers the same provider refund by lookup',async()=>{
  const {paymentId}=await captured();scenario='lost-response';const r=await issueRefund(paymentId);await refundService.runOnce();expect((await refundRepo.get(r.id)).status).toBe('REQUIRES_RECONCILIATION');
  const applicationName=`refund_disconnect_${payments.schema}`,disrupted=new Pool({...payments.config,application_name:applicationName,options:`-c search_path=${payments.schema}`});
  const repo=new RefundRepository(disrupted,keys,100,10,async point=>{
   if(point==='before_outcome_commit'){
    const targets=(await payments.pool.query("SELECT pid FROM pg_stat_activity WHERE datname=current_database() AND usename=current_user AND application_name=$1 AND state='idle in transaction'",[applicationName])).rows;expect(targets).toHaveLength(1);
    await payments.pool.query('SELECT pg_terminate_backend($1)',[targets[0].pid]);
   }
  });
  try{await expect(deliveryService(repo,new ProviderClient(providerUrl,1000)).reconcile(r.id)).rejects.toThrow();expect((await refundRepo.get(r.id)).status).toBe('REQUIRES_RECONCILIATION');expect(await events(payments,'payment.refund_succeeded')).toHaveLength(0);expect(await providerRefunds()).toHaveLength(1);}finally{await disrupted.end();}
  await makeDue();await refundService.runOnce();expect((await refundRepo.get(r.id)).status).toBe('SUCCEEDED');expect(await providerRefunds()).toHaveLength(1);
 });
});
describe('Durable refund rejection',()=>{
 it('does not turn a rejected refund command into a new financial operation when capacity later becomes available',async()=>{
  const {order,paymentId}=await captured();scenario='ambiguous';const partial=await issueRefund(paymentId,40);await refundService.runOnce();
  await saga.cancel(userId,false,order.id,'cancel');await refundCancellation();expect((await row()).state).toBe('CANCELLATION_FAILED');
  const cmd=await command('payment.refund.requested');if(cmd.eventType!=='payment.refund.requested')throw new Error();expect((await refundRepo.get(cmd.payload.refundId)).status).toBe('FAILED');
  await mockPool.query("UPDATE mock_refunds SET status='FAILED',failure_code='PROVIDER_DECLINED' WHERE operation_id=$1",[partial.provider_operation_id]);await refundService.reconcile(partial.id);
  await refundConsumer(sagaEvent(cmd.eventType,cmd.payload,keys,cmd.correlationId,cmd),context);await makeDue();await refundService.runOnce();
  expect((await refundRepo.get(cmd.payload.refundId)).status).toBe('FAILED');expect(await providerRefunds()).toHaveLength(1);expect((await row()).state).toBe('CANCELLATION_FAILED');
 });
});
